export interface HeartbeatPayload {
  readonly seatId: number;
  readonly status: 'active' | 'stale';
  readonly timestampEpoch: number;
}

export interface LockAcquiredPayload {
  readonly seatId: number;
  readonly resourcePath: string;
  readonly leaseEpoch: number;
}

export interface TaskDispatchedPayload {
  readonly taskId: string;
  readonly seatId: number;
  readonly payloadJson: string;
}

export type MeshProtocolEvent =
  | { readonly kind: 'HEARTBEAT'; readonly data: HeartbeatPayload }
  | { readonly kind: 'LOCK_ACQUIRED'; readonly data: LockAcquiredPayload }
  | { readonly kind: 'TASK_DISPATCHED'; readonly data: TaskDispatchedPayload };

export function assertNever(x: never, message?: string): never {
  throw new Error(message ?? `Unexpected unreachable value: ${JSON.stringify(x)}`);
}

export function processMeshEvent(event: MeshProtocolEvent): string {
  switch (event.kind) {
    case 'HEARTBEAT':
      return `[HB] Seat ${event.data.seatId} is ${event.data.status}`;
    case 'LOCK_ACQUIRED':
      return `[LOCK] Seat ${event.data.seatId} locked ${event.data.resourcePath}`;
    case 'TASK_DISPATCHED':
      return `[TASK] Task ${event.data.taskId} dispatched to Seat ${event.data.seatId}`;
    default:
      return assertNever(event);
  }
}

